    const firstExecution = harness.service.executeExternalLifecycle({
      appId: APP_ID,
      output: first.output,
      operation: "restart",
      invocationRef: REF,
    });
    const secondExecution = harness.service.executeExternalLifecycle({
      appId: APP_ID,
