          },
        },
      ],
    };
    const enqueue = vi.fn((_event: ImageGenerationEvent) => ({
      settled: Promise.resolve({ kind: "applied" }),
    }));
    const fence = {
      key: { collection: "default" },
      generation: { ordinal: 1, identity: {} },
      seal: vi.fn(async () => undefined),
      commit: vi.fn(() => true),
      abort: vi.fn(() => true),
      release: vi.fn(() => true),
