      disposeMachine: vi.fn(),
      beginFence: vi.fn(() => fence),
    } as never);

    const deletion = actorService.beginAppDeletion(7);
    await actorService.finishAppDeletion(deletion, false);

    expect(fence.abort).toHaveBeenCalledOnce();
