    expect(buildConfigForFramework("vite")).toEqual({
      buildPack: "railpack",
      portsExposes: "3000",
      startCommand: undefined,
    });
  });

  it("names the entry point of a Vite app that gained a Nitro server", () => {
    // Still a Vite build, so railpack reads its config as a static site.
    // Naming what to run is what stops it being served as one.
    expect(buildConfigForFramework("vite-nitro")).toEqual({
      buildPack: "railpack",
      portsExposes: "3000",
      startCommand: "node .output/server/index.mjs",
    });
  });

  it("defers to the app when it names its own entry point", () => {
    // Empty, not absent. Coolify keeps a start command once given one and
    // prefers it over the app's own script, so an app converted before it
    // wrote a `start` script would go on running the value an earlier deploy
    // left behind. Sending "" is what hands priority back to the app.
    expect(
      buildConfigForFramework("vite-nitro", { declaresStart: true })
        .startCommand,
    ).toBe("");
  });

  it("leaves a start command alone for a framework Dyad never sets one for", () => {
    // Next.js carries `next start`, so Dyad has never supplied a command for
    // it — and a value the user set in Coolify is theirs, not a stale one of
    // ours to clear.
    expect(
      buildConfigForFramework("nextjs", { declaresStart: true }).startCommand,
    ).toBeUndefined();
  });

  it("says nothing at all about Next.js", () => {
    // Railpack detects it and every scaffold carries `next start`.
    expect(buildConfigForFramework("nextjs")).toEqual({
      buildPack: "railpack",
      portsExposes: "3000",
      startCommand: undefined,
    });
  });

  // Driven off the constant rather than a hand-written list: a new framework
  // type then fails here until someone decides how Coolify should build it.
  describe.each([...APP_FRAMEWORK_TYPES, null])(
    "every framework type (%s)",
    (framework: AppFrameworkType | null) => {
      const config = buildConfigForFramework(framework);

      it("builds with railpack", () => {
        expect(config.buildPack).toBe("railpack");
      });

      it("always names a port", () => {
        // Coolify will not route to an application that exposes none.
        expect(config.portsExposes).toMatch(/^\d+$/);
      });

      it("claims nothing beyond the build pack, the port, and a start command", () => {
        // Everything else is the build pack's to decide, and a field Dyad
        // does not send is one Coolify keeps as already configured.
        expect(Object.keys(config).sort()).toEqual([
          "buildPack",
          "portsExposes",
          "startCommand",
        ]);
      });
    },
  );
});

import { describe, expect, it } from "vitest";
import { assertCapabilityTransitionConsistency } from "@/state_machines/testing";
import { selectCoolifyDeployCapabilities } from "./capabilities";
import { transition } from "./transition";
import {
  COOLIFY_DEPLOY_INVOCATION_KIND,
  type CoolifyDeployEvent,
  type CoolifyDeployState,
} from "./state";

const APP_ID = 1;

const invocationRef = {
  kind: COOLIFY_DEPLOY_INVOCATION_KIND,
  entityKey: APP_ID,
  operationId: "coolify-deploy:1",
} as const;

const states: CoolifyDeployState[] = [
  { type: "idle" },
  {
    type: "running",
    appId: APP_ID,
    invocationRef,
    stage: "building",
    log: "",
    startedAt: 1,
    deploymentUuid: "dep-1",
  },
  {
    type: "succeeded",
    appId: APP_ID,
    log: "",
    url: "https://app.example.com",
    finishedAt: 2,
  },
  {
    type: "failed",
    appId: APP_ID,
    log: "",
    error: "boom",
    finishedAt: 2,
    deploymentUuid: "dep-1",
  },
];

const deployRequested: CoolifyDeployEvent = {
  type: "DEPLOY_REQUESTED",
  appId: APP_ID,
  invocationRef: { ...invocationRef, operationId: "coolify-deploy:2" },
  startedAt: 3,
};

describe("coolify_deploy capabilities", () => {
  it("keeps every enabled control consistent with the transition", () => {
    expect(() =>
      assertCapabilityTransitionConsistency({
        states,
        // canEditConnection guards a database write rather than a machine
        // event, so there is no transition for it to agree with.
        selectCapabilities: (state: CoolifyDeployState) => ({
          canDeploy: selectCoolifyDeployCapabilities(state).canDeploy,
        }),
        transition,
        cases: {
          canDeploy: {
            representativeEvents: () => ({ valid: [deployRequested] }),
            disabledReason: "already-running",
          },
        },
      }),
    ).not.toThrow();
  });

  it("blocks deploying and editing the connection only while one is running", () => {
    const running = states.find((s) => s.type === "running")!;
    expect(selectCoolifyDeployCapabilities(running)).toEqual({
      canDeploy: false,
      canEditConnection: false,
    });
    // Every other state allows both, including the two terminal ones — which
    // is what "only while one is running" claims.
    for (const state of states.filter((s) => s.type !== "running")) {
      expect(selectCoolifyDeployCapabilities(state)).toEqual({
        canDeploy: true,
        canEditConnection: true,
      });
    }
  });
});

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ipc } from "@/ipc/types";
import { queryKeys } from "@/lib/queryKeys";
import type { LegacyTestFile } from "@/ipc/types/tests";

export type { LegacyTestFile };

/**
 * Detect Playwright specs still living in the legacy `tests/` directory for an
 * app. `enabled` gates the scan (e.g. run it only when the Tests panel is
 * engaged and the migration offer hasn't been dismissed). Detection failing is
 * non-critical — the offer simply won't show — so no error toast is surfaced.
 */
export function useLegacyTests(appId: number | null, enabled: boolean) {
  return useQuery({
    queryKey: queryKeys.tests.legacy({ appId }),
    queryFn: async (): Promise<{ files: LegacyTestFile[] }> => {
      if (appId == null) {
        return { files: [] };
      }
      return ipc.tests.detectLegacyTests({ appId });
    },
    enabled: enabled && appId != null,
  });
}

/**
 * Move selected legacy specs from `tests/` into `e2e-tests/`. On success,
 * refreshes the panel's spec list (migrated specs appear) and re-runs legacy
 * detection (so the banner self-clears once the files are gone from `tests/`).
 */
export function useMigrateLegacyTests() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (params: { appId: number; files: string[] }) =>
      ipc.tests.migrateLegacyTests(params),
    onSuccess: (_result, { appId }) => {
      void queryClient.invalidateQueries({
        queryKey: queryKeys.tests.list({ appId }),
      });
      void queryClient.invalidateQueries({
        queryKey: queryKeys.tests.legacy({ appId }),
      });
    },
  });
}

import { useEffect, useRef, type PropsWithChildren } from "react";
import {
  dismissImageGenerationToast,
  showImageGeneratingToast,
  showImageSuccessToast,
} from "@/components/ImageGenerationToast";
import { ipc } from "@/ipc/types";
import { showError } from "@/lib/toast";
import { ImageGenerationRequestScopeProvider } from "./request_scope";

export function ImageGenerationProvider({ children }: PropsWithChildren) {
  const pendingCountRef = useRef(0);
  useEffect(() => {
    const unsubscribe = ipc.events.imageGeneration.onPresentation((event) => {
      pendingCountRef.current = event.pendingCount;
      if (event.type === "succeeded") {
        showImageSuccessToast(event.result, () => pendingCountRef.current);
        return;
      }
      if (event.pendingCount > 0) {
        showImageGeneratingToast(event.pendingCount);
      } else {
        dismissImageGenerationToast();
      }
      if (event.type === "failed") showError(event.message);
    });
    return () => {
      unsubscribe();
      dismissImageGenerationToast();
    };
  }, []);

  return (
    <ImageGenerationRequestScopeProvider>
      {children}
    </ImageGenerationRequestScopeProvider>
  );
}

import type { AppFrameworkType } from "@/lib/framework_constants";

// Tags must occupy their own line — guide bodies mention the literal strings
// `<nextjs-only>` / `<vite-nitro-only>` inline (e.g. "Follow the `<nextjs-only>`
// section below."), and a loose regex would gobble everything between them.
const NEXTJS_BLOCK = /^<nextjs-only>$[\s\S]*?^<\/nextjs-only>$\n?/gm;
const VITE_NITRO_BLOCK =
  /^<vite-nitro-only>$[\s\S]*?^<\/vite-nitro-only>$\n?/gm;
const NEXTJS_TAGS = /^<\/?nextjs-only>$\n?/gm;
const VITE_NITRO_TAGS = /^<\/?vite-nitro-only>$\n?/gm;
// Non-global twins for existence checks — reusing the /g variants would mutate
// `lastIndex` between calls and produce inconsistent results.
const HAS_NEXTJS_BLOCK = /^<nextjs-only>$[\s\S]*?^<\/nextjs-only>$/m;
const HAS_VITE_NITRO_BLOCK = /^<vite-nitro-only>$[\s\S]*?^<\/vite-nitro-only>$/m;

/**
 * Strip the framework section that doesn't apply to the current runtime from
 * a guide's markdown. Guides bundle both the Next.js and Vite + Nitro paths
 * for ease of maintenance; we only ship the one that matches.
 *
 * Plain "vite" maps to the Vite + Nitro path because Dyad adds a Nitro layer
 * when Neon is connected to a Vite app.
 *
 * Unknown frameworks ("other", null) keep both sections — the caller doesn't
 * have enough signal to choose.
 */
export function filterGuideByFramework(
  markdown: string,
  frameworkType: AppFrameworkType | null,
): string {
  if (!HAS_NEXTJS_BLOCK.test(markdown)) {
    throw new Error(
      "Guide is missing required <nextjs-only>...</nextjs-only> block",
    );
  }
  if (!HAS_VITE_NITRO_BLOCK.test(markdown)) {
    throw new Error(
      "Guide is missing required <vite-nitro-only>...</vite-nitro-only> block",
    );
  }
  if (frameworkType === "nextjs") {
    return markdown.replace(VITE_NITRO_BLOCK, "").replace(NEXTJS_TAGS, "");
  }
  if (frameworkType === "vite-nitro" || frameworkType === "vite") {
    return markdown.replace(NEXTJS_BLOCK, "").replace(VITE_NITRO_TAGS, "");
  }
  return markdown.replace(NEXTJS_TAGS, "").replace(VITE_NITRO_TAGS, "");
}

import type { AppFrameworkType } from "@/lib/framework_constants";
import { filterGuideByFramework } from "./filter_guide_by_framework";

/** Resolve runtime-specific guidance before sending a guide to the model. */
export function renderGuide(
  markdown: string,
  frameworkType: AppFrameworkType | null,
  { enableAppPreviewDomains = false }: { enableAppPreviewDomains?: boolean } = {},
): string {
  return filterGuideByFramework(markdown, frameworkType).replace(
    "[[PREVIEW_COOKIE_GUIDANCE]]",
    enableAppPreviewDomains
      ? "Dyad previews use stable `app-<numeric app ID>.localhost` hostnames and strip cookie `Domain` attributes, so each app keeps its own host-only session."
      : "Dyad previews use `localhost` with shared cookies across ports.",
  );
}

# Internationalization (i18n) Design

## Overview

This document describes the i18n system for Dyad. The goal is to support multiple languages across the Electron renderer and main process with type-safe translation keys, minimal boilerplate, and incremental adoption.

## Library: `react-i18next` + `i18next`

Use `react-i18next` (the de facto standard for React i18n) rather than building a custom solution.

Rationale:

- Mature ecosystem with broad community support
- Built-in pluralization, interpolation, nesting, and context support
- ICU message format support via plugin when needed
- TypeScript support for key autocompletion
- Works in both renderer (React) and main process (plain `i18next`)
- Lazy-loading of translation namespaces out of the box

### Dependencies

```
npm install i18next react-i18next
```

No additional plugins are needed initially. Translation files are bundled with the app (not fetched remotely), so no HTTP backend is required.

## Translation file structure

```
src/
  i18n/
    index.ts              # i18next initialization
    types.ts              # Generated types for key autocompletion
    locales/
      en/
        common.json       # Shared strings (buttons, labels, generic)
        settings.json     # Settings page
        chat.json         # Chat UI
        home.json         # Home page
        errors.json       # Error/toast messages
      zh-CN/
        common.json
        settings.json
        ...
      ja/
        common.json
        ...
```

### Namespace strategy

Split translations by feature area (namespace = one JSON file). This keeps files manageable and allows lazy-loading namespaces for routes that aren't immediately visible.

| Namespace      | Scope                                       |
| -------------- | ------------------------------------------- |
| `common`       | Buttons, generic labels, confirmations, nav |
| `settings`     | All settings page sections                  |
| `chat`         | Chat input, messages, streaming indicators  |
| `home`         | Home page, app list, templates              |
| `errors`       | Toast messages, error dialogs, validation   |
| `hub`          | Hub/library/marketplace                     |
| `integrations` | GitHub, Supabase, Neon, Vercel connectors   |

### Translation file format

Standard flat-key JSON with nesting where it aids organization:

```json
// en/settings.json
{
  "title": "Settings",
  "general": {
    "title": "General",
    "language": "Language",
    "zoom": "Zoom Level",
    "theme": "Theme"
  },
  "ai": {
    "title": "AI",
    "model": "Model",
    "provider": "Provider",
    "apiKey": "API Key"
  },
  "agent": {
    "toolPermissions": "Configure permissions for Agent built-in tools.",
    "permissionOption": {
      "ask": "Ask",
      "always": "Always allow",
      "never": "Never allow"
    }
  }
}
```

```json
// en/common.json
{
  "save": "Save",
  "cancel": "Cancel",
  "delete": "Delete",
  "confirm": "Confirm",
  "loading": "Loading...",
  "copyToClipboard": "Copy to clipboard",
  "copied": "Copied!",
  "itemCount_one": "{{count}} item",
  "itemCount_other": "{{count}} items"
}
```

Pluralization uses i18next's built-in suffix convention (`_one`, `_other`, `_zero`, etc.), which handles most languages. For languages with complex plural rules (e.g., Arabic, Polish), i18next resolves the correct form automatically.

## Initialization

```typescript
// src/i18n/index.ts
import i18n from "i18next";
import { initReactI18next } from "react-i18next";

// Import all locale bundles (bundled with the app)
import enCommon from "./locales/en/common.json";
import enSettings from "./locales/en/settings.json";
import enChat from "./locales/en/chat.json";
import enHome from "./locales/en/home.json";
import enErrors from "./locales/en/errors.json";
// ... other languages imported similarly

const resources = {
  en: {
    common: enCommon,
    settings: enSettings,
    chat: enChat,
    home: enHome,
    errors: enErrors,
  },
  // "zh-CN": { ... },
  // "ja": { ... },
};

i18n.use(initReactI18next).init({
  resources,
  lng: "en", // Default; overridden by user setting on startup
  fallbackLng: "en",
  defaultNS: "common",
  ns: ["common", "settings", "chat", "home", "errors"],
  interpolation: {
    escapeValue: false, // React already escapes
  },
});

export default i18n;
```

Import `src/i18n/index.ts` at the app entry point (`src/main.tsx` or equivalent) before rendering.

## React usage

### `useTranslation` hook

```tsx
import { useTranslation } from "react-i18next";

function AgentToolsSettings() {
  const { t } = useTranslation("settings");

  return (
    <div>
      <p className="text-sm text-muted-foreground">
        {t("agent.toolPermissions")}
      </p>
      <SelectItem value="ask">{t("agent.permissionOption.ask")}</SelectItem>
      <SelectItem value="always">
        {t("agent.permissionOption.always")}
      </SelectItem>
    </div>
  );
}
```

### Multiple namespaces

```tsx
const { t } = useTranslation(["settings", "common"]);

// Keys from the first namespace work directly
t("general.title"); // → "General" (from settings)

// Keys from other namespaces use prefix
t("common:save"); // → "Save" (from common)
```

### Interpolation

```tsx
t("errors:fileNotFound", { path: "/some/file.txt" });
// "File not found: {{path}}" → "File not found: /some/file.txt"
```

### Components with embedded markup

Use the `Trans` component for strings that contain JSX:

```tsx
import { Trans } from "react-i18next";

<Trans i18nKey="home:welcome" t={t}>
  Welcome to <strong>Dyad</strong>
</Trans>;
```

## Type safety

### Generating types from translation files

Create a type declaration so that `t("...")` calls get autocompletion and compile-time checking of keys.

```typescript
// src/i18n/types.ts
import "i18next";
import type enCommon from "./locales/en/common.json";
import type enSettings from "./locales/en/settings.json";
import type enChat from "./locales/en/chat.json";
import type enHome from "./locales/en/home.json";
import type enErrors from "./locales/en/errors.json";

declare module "i18next" {
  interface CustomTypeOptions {
    defaultNS: "common";
    resources: {
      common: typeof enCommon;
      settings: typeof enSettings;
      chat: typeof enChat;
      home: typeof enHome;
      errors: typeof enErrors;
    };
  }
}
```

This gives full autocomplete for `t("settings:general.title")` etc., and TypeScript errors for invalid keys.

## Language setting integration

### User settings

Add a `language` field to `UserSettingsSchema` in `src/lib/schemas.ts`:

```typescript
// In UserSettingsSchema
language: z.string().default("en"),
```

### Settings UI

Add a language selector to the General settings section (similar to the existing zoom selector):

```tsx
function LanguageSelector() {
  const { t } = useTranslation("settings");
  const [settings, setSettings] = useSettings();

  const languages = [
    { value: "en", label: "English" },
    { value: "zh-CN", label: "简体中文" },
    { value: "ja", label: "日本語" },
    { value: "ko", label: "한국어" },
    { value: "es", label: "Español" },
    { value: "fr", label: "Français" },
    { value: "de", label: "Deutsch" },
  ];

  const handleChange = (value: string) => {
    i18n.changeLanguage(value);
    setSettings({ ...settings, language: value });
  };

  return (
    <Select value={settings.language} onValueChange={handleChange}>
      {languages.map((lang) => (
        <SelectItem key={lang.value} value={lang.value}>
          {lang.label}
        </SelectItem>
      ))}
    </Select>
  );
}
```

Language labels are shown in their native script (not translated) so users can always find their language regardless of the current UI language.

### Startup sync

On app startup, read the persisted language from user settings and call `i18n.changeLanguage(savedLanguage)` before the first render. This can be done in the settings loading hook or in `src/i18n/index.ts` by reading the setting synchronously.

## Electron main process strings

Some user-facing strings originate in the main process (e.g., native dialogs, menu items, error messages sent over IPC). For these:

1. Import `i18next` directly (without `react-i18next`) in main process code.
2. Share the same locale JSON files.
3. Initialize a separate i18next instance in `src/main/i18n.ts`.

```typescript
// src/main/i18n.ts
import i18n from "i18next";
import enErrors from "../i18n/locales/en/errors.json";

const mainI18n = i18n.createInstance();
mainI18n.init({
  resources: { en: { errors: enErrors } },
  lng: "en",
  fallbackLng: "en",
  defaultNS: "errors",
});

export default mainI18n;
```

When the user changes language in the renderer, send the new language to the main process via IPC so it can call `mainI18n.changeLanguage(lng)`.

## Date, number, and relative time formatting

Use the browser's `Intl` API (already available in Electron's Chromium) rather than adding a formatting library:

```typescript
// Utility in src/i18n/format.ts
export function formatDate(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

export function formatNumber(value: number, locale: string): string {
  return new Intl.NumberFormat(locale).format(value);
}

export function formatRelativeTime(date: Date, locale: string): string {
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  const diffMs = date.getTime() - Date.now();
  const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));
  if (Math.abs(diffDays) < 1) {
    const diffHours = Math.round(diffMs / (1000 * 60 * 60));
    return rtf.format(diffHours, "hour");
  }
  return rtf.format(diffDays, "day");
}
```

The existing `date-fns` dependency also supports locale-aware formatting if more complex date operations are needed.

## Incremental adoption strategy

Migrating all strings at once is impractical. Instead, adopt incrementally:

### Phase 1: Infrastructure

- Install dependencies, create `src/i18n/` directory structure, initialize i18next.
- Add `language` to UserSettings schema.
- Create `en/common.json` with the most common shared strings (button labels, generic terms).
- Add the language selector to settings.

### Phase 2: Settings page

- Extract all settings page strings into `en/settings.json`.
- Replace hardcoded strings in settings components with `t()` calls.
- This is a self-contained area with many strings, good for validating the approach.

### Phase 3: Core UI

- Extract chat, home, and error strings into their respective namespace files.
- Convert toast messages in `src/lib/toast.tsx` and callers.
- Convert dialog and modal text.

### Phase 4: First additional language

- Add one complete translation (e.g., `zh-CN`) to validate the full loop.
- Fix any layout issues from longer/shorter translated strings.
- Verify RTL considerations if an RTL language is planned.

### Phase 5: Remaining strings and languages

- Extract remaining hardcoded strings (integrations, hub, etc.).
- Add more language translations.
- Set up a translation workflow (see below).

## Translation workflow

### For contributors

- English is the source of truth. All new strings are added to `en/*.json` first.
- Other language files must mirror the English key structure. Missing keys fall back to English automatically.

### Lint rule

Add a CI check that verifies all keys present in `en/*.json` exist in every other locale. Missing keys produce warnings (not errors, since fallback handles them), making it easy to see translation coverage.

### Extraction (optional tooling)

Consider `i18next-parser` to scan source files for `t("...")` calls and auto-generate/update the English JSON files. This catches strings that were added in code but not in the JSON.

```json
// package.json script
"i18n:extract": "i18next-parser 'src/**/*.{ts,tsx}'"
```

## Key conventions

| Convention                     | Example                                                |
| ------------------------------ | ------------------------------------------------------ |
| Namespace maps to feature area | `settings`, `chat`, `common`                           |
| Nested keys use dot notation   | `settings:general.title`                               |
| Action labels are imperative   | `"save": "Save"`, `"delete": "Delete"`                 |
| Descriptions are sentence case | `"toolPermissions": "Configure permissions..."`        |
| Plurals use i18next suffixes   | `_one`, `_other`                                       |
| Interpolation uses `{{var}}`   | `"hello": "Hello, {{name}}"`                           |
| No string concatenation        | Use interpolation instead of `t("a") + value + t("b")` |

## What NOT to translate

- Log messages and debug output (keep in English for debugging)
- IPC channel names and internal identifiers
- Database column names and schema identifiers
- Error stack traces
- Third-party API responses

import { MakerBase, MakerOptions } from "@electron-forge/maker-base";
import { execFile } from "child_process";
import {
  writeFile,
  appendFile,
  mkdtemp,
  mkdir,
  cp,
  symlink,
  chmod,
  readFile,
  copyFile,
  rm,
} from "fs/promises";
import { tmpdir } from "os";
import { promisify } from "util";
import { resolve, relative, extname } from "path";
import { createHash } from "crypto";

// AppImage runtime version and location
const RUNTIME_VERSION = "20251108";
const RUNTIME_URL = `https://github.com/AppImage/type2-runtime/releases/download/${RUNTIME_VERSION}/runtime-x86_64`;

// SHA256 hash of the expected runtime binary
// Can be generated with: curl -sL <URL> | sha256sum
// Also visible directly on the GitHub releases page; see 'runtime-x86_64' on:
// https://github.com/AppImage/type2-runtime/releases/tag/20251108
const RUNTIME_SHA256 =
  "2fca8b443c92510f1483a883f60061ad09b46b978b2631c807cd873a47ec260d";

// For creating temporary work directories; largely arbitrary
const APPDIR_PREFIX = "AppDir";
const WORKDIR_PREFIX = "AppImageWorkDir";

/**
 * Minimalist Forge maker for AppImages
 */
export class MakerAppImage extends MakerBase<{ icon?: string }> {
  override defaultPlatforms = ["linux"];
  override name = "AppImage";
  override requiredExternalBinaries = ["mksquashfs"];

  override isSupportedOnCurrentPlatform(): boolean {
    return process.platform === "linux" && process.arch === "x64";
  }

  override async make({
    appName,
    dir,
    makeDir,
    packageJSON,
  }: MakerOptions): Promise<string[]> {
    const version = packageJSON["version"];

    if (!version || typeof version !== "string")
      throw new Error("Could not access version information");

    const { icon } = this.config;

    const exeName = `${appName}_${version}_x86_64.AppImage`;
    const outputDir = resolve(makeDir, "AppImage");
    const outputFilePath = resolve(outputDir, exeName);

    // Fetch AppImage runtime
    const res = await fetch(RUNTIME_URL, {
      signal: AbortSignal.timeout(10000), // 10 second timeout
    });

    if (!res.ok)
      throw new Error(
        `Could not fetch AppImage runtime: ${res.status} ${res.statusText}`,
      );

    const runtime = Buffer.from(await res.arrayBuffer());

    // Verify SHA256 hash
    const hash = createHash("sha256").update(runtime).digest("hex");

    if (hash !== RUNTIME_SHA256)
      throw new Error(
        [
          "AppImage runtime integrity check failed.",
          `Expected: ${RUNTIME_SHA256}`,
          `Got:      ${hash}`,
          "The runtime binary may have been tampered with or updated.",
          "If this was intentional, please update RUNTIME_SHA256 in makers/MakerAppImage.ts.",
        ].join("\n"),
      );

    // Names of temporary directories to clean up later
    let appDir: string | undefined;
    let workDir: string | undefined;

    try {
      // Create directory structure of AppDir.
      // For conventions, see: https://docs.appimage.org/reference/appdir.html#conventions
      appDir = await mkdtemp(
        resolve(tmpdir(), `${APPDIR_PREFIX}_${appName}_${version}_`),
      );
      const binDir = resolve(appDir, "usr/bin");
      const libDir = resolve(appDir, `usr/lib/${appName}`);

      await mkdir(binDir, { recursive: true, mode: 0o755 });
      await mkdir(libDir, { recursive: true, mode: 0o755 });

      // Add the actual application code to the AppDir.
      // verbatimSymlinks keeps relative symlinks (e.g. dugite's
      // git-remote-https -> git-remote-http) intact; without it fs.cp rewrites
      // them to absolute build-machine paths that dangle on the user's system.
      await cp(dir, libDir, { recursive: true, verbatimSymlinks: true });

      // Generate .desktop file
      // See: https://docs.appimage.org/reference/desktop-integration.html#desktop-files
      // Also: https://specifications.freedesktop.org/desktop-entry/latest/recognized-keys.html
      const desktopFile = [
        "[Desktop Entry]",
        "Type=Application",
        "Version=1.5",
        `Name=${appName}`,
        ...(icon ? [`Icon=${appName}`] : []),
        "Exec=AppRun %U",
        `X-AppImage-Name=${appName}`,
        `X-AppImage-Version=${version}`,
        "X-AppImage-Arch=x86_64",
      ].join("\n");

      await writeFile(resolve(appDir, `${appName}.desktop`), desktopFile);

      // Add the icon
      if (icon) {
        const ext = extname(icon);

        if (!ext || ext !== ".png")
          throw new Error(`Invalid icon extension: ${ext || "[None]"}`);

        const finalIconName = `${appName}${ext}`;
        const finalIconPath = resolve(appDir, finalIconName);

        await copyFile(icon, finalIconPath);
        await symlink(finalIconName, resolve(appDir, ".DirIcon"), "file");
      }

      // By convention, executables should be in /bin
      await symlink(
        relative(binDir, resolve(libDir, appName)),
        resolve(binDir, appName),
        "file",
      );

      // The entry point of an AppImage should be the AppRun file.
      // See: https://docs.appimage.org/reference/appdir.html#general-description
      await symlink(
        relative(appDir, resolve(binDir, appName)),
        resolve(appDir, "AppRun"),
        "file",
      );

      // mksquashfs emits a file, so we create a temporary file
      // inside a temporary directory to hold the output
      workDir = await mkdtemp(
        resolve(tmpdir(), `${WORKDIR_PREFIX}_${appName}_${version}_`),
      );
      const tempSquashedFsPath = resolve(workDir, "temp");

      const execFileAsync = promisify(execFile);

      try {
        await execFileAsync("mksquashfs", [appDir, tempSquashedFsPath]);
      } catch (err: any) {
        const stderr = err?.stderr?.toString?.() ?? "";
        const stdout = err?.stdout?.toString?.() ?? "";

        throw new Error(
          [
            "mksquashfs failed",
            `exit code: ${err?.code ?? "unknown"}`,
            stderr && `stderr:\n${stderr}`,
            stdout && `stdout:\n${stdout}`,
          ]
            .filter(Boolean)
            .join("\n"),
        );
      }

      // Directory to hold final executable
      await mkdir(outputDir, { recursive: true, mode: 0o755 });

      // Per the documentation, AppImages should consist
      // of the runtime prepended to the squashed fs.
      // See: https://docs.appimage.org/reference/architecture.html
      await writeFile(outputFilePath, runtime);
      await appendFile(outputFilePath, await readFile(tempSquashedFsPath));

      await chmod(outputFilePath, 0o755);

      return [outputFilePath];
    } finally {
      // Clean up temporary directories
      if (appDir)
        await rm(appDir, {
          recursive: true,
          force: true,
        });

      if (workDir)
        await rm(workDir, {
          recursive: true,
          force: true,
        });
    }
  }
}

import { atom } from "jotai";
/** Tracks dismissed job IDs globally so dismissals persist across mounts. */
export const dismissedImageGenerationJobIdsAtom = atom<Set<string>>(
  new Set<string>(),
);

import { useState, useCallback } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Loader2, Sparkles, PenLine } from "lucide-react";
import { useCreateCustomTheme } from "@/hooks/useCustomThemes";
import { showError } from "@/lib/toast";
import { toast } from "sonner";
import { AIGeneratorTab } from "./AIGeneratorTab";

interface CustomThemeDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onThemeCreated?: (themeId: number) => void; // callback when theme is created
}

export function CustomThemeDialog({
  open,
  onOpenChange,
  onThemeCreated,
}: CustomThemeDialogProps) {
  const [activeTab, setActiveTab] = useState<"manual" | "ai">("ai");

  // Manual tab state
  const [manualName, setManualName] = useState("");
  const [manualDescription, setManualDescription] = useState("");
  const [manualPrompt, setManualPrompt] = useState("");

  // AI tab state (shared with AIGeneratorTab)
  const [aiName, setAiName] = useState("");
  const [aiDescription, setAiDescription] = useState("");
  const [aiGeneratedPrompt, setAiGeneratedPrompt] = useState("");

  const createThemeMutation = useCreateCustomTheme();

  const resetForm = useCallback(() => {
    setManualName("");
    setManualDescription("");
    setManualPrompt("");
    setAiName("");
    setAiDescription("");
    setAiGeneratedPrompt("");
    setActiveTab("ai");
  }, []);

  const handleClose = useCallback(async () => {
    resetForm();
    onOpenChange(false);
  }, [onOpenChange, resetForm]);

  const handleSave = useCallback(async () => {
    const isManual = activeTab === "manual";
    const name = isManual ? manualName : aiName;
    const description = isManual ? manualDescription : aiDescription;
    const prompt = isManual ? manualPrompt : aiGeneratedPrompt;

    if (!name.trim()) {
      showError("Please enter a theme name");
      return;
    }
    if (!prompt.trim()) {
      showError(
        isManual
          ? "Please enter a theme prompt"
          : "Please generate a prompt first",
      );
      return;
    }

    try {
      const createdTheme = await createThemeMutation.mutateAsync({
        name: name.trim(),
        description: description.trim() || undefined,
        prompt: prompt.trim(),
      });
      toast.success("Custom theme created successfully");
      onThemeCreated?.(createdTheme.id);
      await handleClose();
    } catch (error) {
      showError(
        `Failed to create theme: ${error instanceof Error ? error.message : "Unknown error"}`,
      );
    }
  }, [
    activeTab,
    manualName,
    manualDescription,
    manualPrompt,
    aiName,
    aiDescription,
    aiGeneratedPrompt,
    createThemeMutation,
    onThemeCreated,
    handleClose,
  ]);

  const isSaving = createThemeMutation.isPending;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Create Custom Theme</DialogTitle>
          <DialogDescription>
            Create a custom theme using manual configuration or AI-powered
            generation.
          </DialogDescription>
        </DialogHeader>

        <Tabs
          value={activeTab}
          onValueChange={(v) => setActiveTab(v as "manual" | "ai")}
          className="mt-4"
        >
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="ai" className="flex items-center gap-2">
              <Sparkles className="h-4 w-4" />
              AI-Powered Generator
            </TabsTrigger>
            <TabsTrigger value="manual" className="flex items-center gap-2">
              <PenLine className="h-4 w-4" />
              Manual Configuration
            </TabsTrigger>
          </TabsList>

          {/* AI-Powered Generator Tab */}
          <TabsContent value="ai">
            <AIGeneratorTab
              aiName={aiName}
              setAiName={setAiName}
              aiDescription={aiDescription}
              setAiDescription={setAiDescription}
              aiGeneratedPrompt={aiGeneratedPrompt}
              setAiGeneratedPrompt={setAiGeneratedPrompt}
              onSave={handleSave}
              isSaving={isSaving}
              isDialogOpen={open}
            />
          </TabsContent>

          {/* Manual Configuration Tab */}
          <TabsContent value="manual" className="space-y-4 mt-4">
            <div className="space-y-2">
              <Label htmlFor="manual-name">Theme Name</Label>
              <Input
                id="manual-name"
                placeholder="My Custom Theme"
                value={manualName}
                onChange={(e) => setManualName(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="manual-description">Description (optional)</Label>
              <Input
                id="manual-description"
                placeholder="A brief description of your theme"
                value={manualDescription}
                onChange={(e) => setManualDescription(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="manual-prompt">Theme Prompt</Label>
              <Textarea
                id="manual-prompt"
                placeholder="Enter your theme system prompt..."
                className="min-h-[200px] font-mono text-sm"
                value={manualPrompt}
                onChange={(e) => setManualPrompt(e.target.value)}
              />
            </div>

            <Button
              onClick={handleSave}
              disabled={isSaving || !manualName.trim() || !manualPrompt.trim()}
              className="w-full"
            >
              {isSaving ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Saving...
                </>
              ) : (
                "Save Theme"
              )}
            </Button>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}
